const ctx = $input.first().json;
const config = $('Config').first().json;
if (!ctx.profile?.id || ctx.profile.status !== 'approved') {
  throw new Error('CONTENT_STUDIO: Approve the business profile in admin.');
}

const competitorText = String(ctx.profile.data?.competitors ?? '').trim();
if (!competitorText) {
  throw new Error('CONTENT_STUDIO: Business profile → Competitor websites and notes is empty. Add your 20 competitors there and Approve the profile.');
}

function extractUrls(text) {
  const urls = new Set();
  for (const m of text.matchAll(/https?:\/\/[^\s)\]>"']+/gi)) urls.add(m[0].replace(/[.,;]+$/, ''));
  for (const m of text.matchAll(/\b(?:www\.)?([a-z0-9][-a-z0-9]*(?:\.[a-z0-9][-a-z0-9]*)+\.[a-z]{2,})(?:\/[^\s]*)?/gi)) {
    let u = m[0].replace(/[.,;]+$/, '');
    if (!/^https?:\/\//i.test(u)) u = `https://${u}`;
    urls.add(u);
  }
  return [...urls];
}

const urls = extractUrls(competitorText).slice(0, 15);
const snapshots = [];
for (const url of urls) {
  try {
    const body = await this.helpers.httpRequest({
      method: 'GET',
      url,
      timeout: 12000,
      headers: { 'User-Agent': 'SilentCPO-TopicResearch/1.0 (internal)' },
      json: false,
    });
    const snippet = String(body).replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 4000);
    snapshots.push({ url, snippet, fetched: true });
  } catch (error) {
    snapshots.push({ url, snippet: `(Could not fetch: ${error.message})`, fetched: false });
  }
}

const lines = competitorText.split(/\n/).map((l) => l.trim()).filter(Boolean);

return [{
  json: {
    ...ctx,
    siteBaseUrl: config.siteBaseUrl,
    openAiModel: config.openAiModel,
    maxTopics: config.maxTopics,
    competitorSnapshots: snapshots,
    competitorNotes: competitorText,
    competitorResearch: {
      source: 'Admin → Content → Business profile → Competitor websites and notes (approved profile)',
      competitorLines: lines.length,
      urlsDetected: urls.length,
      pagesFetched: snapshots.filter((s) => s.fetched).length,
      urlsAttempted: urls,
    },
  },
}];

const row = $input.first().json;
const p = row.profile.data;
const maxTopics = Number(row.maxTopics) || 30;

const catalog = (row.existingTopics ?? []).map((t) => ({
  title: t.title,
  keyword: t.data?.keyword,
  status: t.status,
}));
const articles = (row.existingArticles ?? []).map((a) => a.title);

const listBlock = row.competitorNotes || '';
const fetchBlock = (row.competitorSnapshots ?? [])
  .map((s) => `URL: ${s.url}\n${s.snippet}`)
  .join('\n\n---\n\n');

const system = [
  'You are an SEO topic strategist for SilentCPO (UK bespoke web/apps studio).',
  'Use the competitor list and page extracts to find content gaps SilentCPO can own honestly.',
  'Never invent search volume, difficulty, or ranking predictions.',
  'British English. Return JSON only.',
].join(' ');

const user = [
  `Return exactly ${maxTopics} blog topics as JSON: { "topics": [ { "title", "keyword", "audience", "intent" (Guide|Comparison|Buying decision|Project story), "rationale", "brief", "priority" (1-5, 1 highest) } ] }. The topics array must have ${maxTopics} items unless impossible without duplicating existing topics.`,
  '',
  '## Business profile',
  `Audience: ${p.audience}`,
  `Services: ${p.services}`,
  `Positioning: ${p.positioning}`,
  `Instructions: ${p.instructions}`,
  `Exclusions: ${p.exclusions}`,
  '',
  '## Competitor list (from approved admin profile — primary source)',
  listBlock,
  '',
  '## Competitor page extracts (auto-fetched from URLs/domains in that list)',
  fetchBlock || '(no URLs fetched — rely on competitor list above)',
  '',
  '## Existing topics (do not duplicate title or keyword)',
  JSON.stringify(catalog),
  '',
  '## Published/draft articles (avoid overlap)',
  articles.join('; ') || '(none)',
].join('\n');

const planKey = `topic-plan-${new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19)}`;

return [{
  json: {
    siteBaseUrl: row.siteBaseUrl,
    planRequestKey: planKey,
    competitorResearch: row.competitorResearch,
    openAiBody: {
      model: row.openAiModel,
      response_format: { type: 'json_object' },
      temperature: 0.5,
      max_tokens: 16000,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
    },
  },
}];

const api = $input.first().json;
const meta = $('Build topic plan prompt').first().json;
const content = api.choices?.[0]?.message?.content;
if (!content) throw new Error('OpenAI: empty topic plan');

let parsed;
try {
  parsed = JSON.parse(content);
} catch {
  throw new Error('OpenAI: topic plan was not valid JSON');
}

const intents = new Set(['Guide', 'Comparison', 'Buying decision', 'Project story']);
const raw = Array.isArray(parsed.topics) ? parsed.topics : [];
if (!raw.length) throw new Error('OpenAI: no topics returned');

const topics = raw.map((t) => ({
  title: String(t.title ?? '').trim().slice(0, 200),
  status: 'ready',
  data: {
    keyword: String(t.keyword ?? '').trim().slice(0, 500),
    audience: String(t.audience ?? '').trim().slice(0, 500),
    intent: intents.has(t.intent) ? t.intent : 'Guide',
    rationale: String(t.rationale ?? '').trim().slice(0, 30000),
    brief: String(t.brief ?? '').trim().slice(0, 30000),
    priority: Math.min(5, Math.max(1, Number(t.priority) || 3)),
    plannedDate: '',
    targetUrl: '',
  },
})).filter((t) => t.title && t.data.keyword);

if (!topics.length) throw new Error('OpenAI: topics missing title or keyword');

return [{
  json: {
    siteBaseUrl: meta.siteBaseUrl,
    competitorResearch: meta.competitorResearch,
    topicsGenerated: topics.length,
    topicPlanBody: {
      requestKey: meta.planRequestKey,
      topics,
    },
  },
}];
